Auth::requireLogin();if(!HrAttendanceRepository::canView()){http_response_code(403);exit('دسترسی غیرمجاز');}$user=Auth::user();
function hr_attendance_input_date(mixed $value):string{$value=trim((string)$value);if($value==='')return date('Y-m-d');return str_contains($value,'/')?(JalaliDate::toGregorian($value)??''):$value;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['csrf_token']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$action=(string)($_POST['action']??'save_batch');if($action==='approve'||$action==='reject'){HrAttendanceRepository::approveOvertime((int)($_POST['entry_id']??0),$action==='approve'?'approved':'rejected',(int)$user['id']);flash($action==='approve'?'اضافه‌کاری تأیید شد.':'اضافه‌کاری رد شد.');}else{$count=HrAttendanceRepository::saveBatch((string)($_POST['attendance_date']??''),(array)($_POST['rows']??[]),(int)$user['id']);flash($count.' رکورد کارکرد ذخیره شد.');}}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('HR attendance: '.$e->getMessage());flash('ثبت کارکرد روزانه انجام نشد.','danger');}$back=hr_attendance_input_date($_POST['attendance_date']??date('Y-m-d'));redirect('/admin/hr-attendance.php?date='.urlencode(JalaliDate::toJalali($back)));}
$inputDate=trim((string)($_GET['date']??JalaliDate::toJalali(date('Y-m-d'))));$date=hr_attendance_input_date($inputDate);if(!$date)$date=date('Y-m-d');$filters=['group_code'=>trim((string)($_GET['group_code']??'')),'org_unit_id'=>(int)($_GET['org_unit_id']??0),'org_role_id'=>(int)($_GET['org_role_id']??0),'sales_line'=>trim((string)($_GET['sales_line']??'')),'supervisor_id'=>(int)($_GET['supervisor_id']??0),'organization_manager_id'=>(int)($_GET['organization_manager_id']??0)];
$rows=HrAttendanceRepository::entriesForDate($date,$filters);$groups=HrAttendanceRepository::groups();$units=HrAttendanceRepository::units();$roles=HrAttendanceRepository::roles();$lines=HrAttendanceRepository::salesLines();$people=HrAttendanceRepository::employees();$logs=HrAttendanceRepository::recentLogs();$logLabels=['create'=>'ایجاد','update'=>'ویرایش','approve_overtime'=>'تأیید اضافه‌کاری','reject_overtime'=>'رد اضافه‌کاری','delete_soft'=>'غیرفعال‌سازی','manual_override'=>'اصلاح دستی'];$pageTitle='ثبت کارکرد روزانه';$adminExtraStylesheets=['/assets/css/hr-attendance.css'];require __DIR__.'/../views/partials/admin-header.php';
