<div class="attendance-page"><header class="attendance-hero"><div><small>حضور، تأخیر، تعجیل و اضافه‌کاری</small><h1>ثبت کارکرد روزانه</h1><p>محاسبه خودکار بر اساس گروه کاری، ساعات مصوب و تقویم تعطیلات</p></div><a class="btn" href="/admin/hr-attendance-reports.php">مشاهده گزارش</a></header><?php require __DIR__.'/includes/hr-attendance-nav.php';?>
<section class="card attendance-filter-card"><form class="attendance-filter" method="get"><label>تاریخ شمسی<input name="date" value="<?=e(JalaliDate::toJalali($date))?>" placeholder="۱۴۰۵/۰۴/۰۸"></label><label>گروه<select name="group_code"><option value="">همه</option><?php foreach($groups as $group):?><option value="<?=e($group['code'])?>" <?=$filters['group_code']===$group['code']?'selected':''?>><?=e($group['title'])?></option><?php endforeach?></select></label><label>واحد<select name="org_unit_id"><option value="">همه</option><?php foreach($units as $item):?><option value="<?=$item['id']?>" <?=$filters['org_unit_id']==$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label>نقش<select name="org_role_id"><option value="">همه</option><?php foreach($roles as $item):?><option value="<?=$item['id']?>" <?=$filters['org_role_id']==$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label>لاین فروش<select name="sales_line"><option value="">همه</option><?php foreach($lines as $line):?><option <?=$filters['sales_line']===$line?'selected':''?>><?=e($line)?></option><?php endforeach?></select></label><label>سرپرست<select name="supervisor_id"><option value="">همه</option><?php foreach($people as $person):?><option value="<?=$person['id']?>" <?=$filters['supervisor_id']==$person['id']?'selected':''?>><?=e($person['name'])?></option><?php endforeach?></select></label><label>مدیر فروش<select name="organization_manager_id"><option value="">همه</option><?php foreach($people as $person):?><option value="<?=$person['id']?>" <?=$filters['organization_manager_id']==$person['id']?'selected':''?>><?=e($person['name'])?></option><?php endforeach?></select></label><div class="attendance-actions"><button class="btn btn-primary">نمایش</button><a class="btn" href="/admin/hr-attendance.php">امروز</a></div></form></section>
<form method="post" class="card"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="save_batch"><input type="hidden" name="attendance_date" value="<?=e(JalaliDate::toJalali($date))?>"><div class="table-wrap"><table class="attendance-table"><thead><tr><th>ثبت</th><th>پرسنل</th><th>گروه</th><th>وضعیت</th><th>ورود</th><th>خروج</th><th>استراحت</th><th>توضیحات</th><th>محاسبات</th></tr></thead><tbody><?php foreach($rows as $person):$entry=$person['entry'];$groupCode=$entry['group_code']??$person['default_group_code'];?><tr><td><input type="checkbox" name="rows[<?=$person['id']?>][selected]" value="1" aria-label="انتخاب <?=e($person['name'])?>"></td><td class="employee-cell"><strong><?=e($person['name'])?></strong><small><?=e(($person['employee_no']?:'بدون شماره').' · '.($person['unit_title']?:$person['department']?:'بدون واحد'))?></small></td><td><select name="rows[<?=$person['id']?>][group_code]"><?php foreach($groups as $group):?><option value="<?=e($group['code'])?>" <?=$groupCode===$group['code']?'selected':''?>><?=e($group['title'])?></option><?php endforeach?></select></td><td><select name="rows[<?=$person['id']?>][day_status]"><?php foreach(HrAttendanceRepository::DAY_STATUSES as $key=>$label):?><option value="<?=$key?>" <?=($entry['day_status']??'present')===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></td><td><input type="time" name="rows[<?=$person['id']?>][actual_in_time]" value="<?=e(substr($entry['actual_in_time']??'',0,5))?>"></td><td><input type="time" name="rows[<?=$person['id']?>][actual_out_time]" value="<?=e(substr($entry['actual_out_time']??'',0,5))?>"></td><td><input type="number" min="0" max="720" name="rows[<?=$person['id']?>][break_minutes]" value="<?=e((string)($entry['break_minutes']??0))?>"></td><td><input name="rows[<?=$person['id']?>][notes]" maxlength="5000" value="<?=e($entry['notes']??'')?>"></td><td><?php if($entry):?><span class="attendance-badge attendance-late">تأخیر <?=$entry['late_minutes']?>د</span> <span class="attendance-badge attendance-early">تعجیل <?=$entry['early_leave_minutes']?>د</span> <span class="attendance-badge attendance-overtime">اضافه‌کاری <?=((int)$entry['normal_overtime_minutes']+(int)$entry['holiday_overtime_minutes'])?>د</span><small><?=e(HrAttendanceRepository::OVERTIME_STATUSES[$entry['overtime_status']]??$entry['overtime_status'])?></small><?php else:?><small>ثبت نشده</small><?php endif?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="9">پرسنلی مطابق فیلتر و محدوده دسترسی یافت نشد.</td></tr><?php endif?></tbody></table></div><?php if(HrAttendanceRepository::canWrite()):?><button class="btn btn-primary">ذخیره ردیف‌های انتخاب‌شده</button><?php endif?></form>
<?php $pending=array_filter($rows,fn($p)=>($p['entry']['overtime_status']??'')==='pending');if($pending&&HrAttendanceRepository::canWrite()):?><section class="card"><h2>اضافه‌کاری‌های در انتظار تأیید</h2><div class="table-wrap"><table><thead><tr><th>پرسنل</th><th>عادی</th><th>تعطیل</th><th></th></tr></thead><tbody><?php foreach($pending as $person):$entry=$person['entry'];?><tr><td><?=e($person['name'])?></td><td><?=$entry['normal_overtime_minutes']?> دقیقه</td><td><?=$entry['holiday_overtime_minutes']?> دقیقه</td><td><div class="attendance-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="attendance_date" value="<?=e(JalaliDate::toJalali($date))?>"><input type="hidden" name="entry_id" value="<?=$entry['id']?>"><button class="btn btn-small" name="action" value="approve">تأیید</button><button class="btn btn-small btn-danger" name="action" value="reject">رد</button></form></div></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>
<?php if($logs):?><section class="card"><h2>آخرین تغییرات ممیزی</h2><div class="table-wrap"><table><thead><tr><th>زمان</th><th>پرسنل</th><th>تاریخ کارکرد</th><th>عملیات</th><th>انجام‌دهنده</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e(JalaliDate::toJalaliDateTime($log['created_at']))?></td><td><?=e($log['employee_name'])?></td><td><?=e(JalaliDate::toJalali($log['attendance_date']))?></td><td><?=e($logLabels[$log['action']]??'تغییر')?></td><td><?=e($log['actor_name']??'سیستم')?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?></div>
